INSERT INTO tq_questions (subjectId, chapterId, type, difficulty, text, explanation, marks, isLegacy, legacyId, isActive) SELECT sj.id, ch.id, 'SINGLE_MCQ', 'MEDIUM', '<p>After tracing the path of rays of light through a glass slab for three different angles of incidence, a student<br /> measured the corresponding values angle of refraction (r) and angle of emergence (e ) and recorded<br /> them in the table given below:</p> <table border="1" cellpadding="1" cellspacing="1"> <tbody> <tr> <td>S.No</td> <td><math xmlns="http://www.w3.org/1998/Math/MathML"><mo>∠</mo></math>i</td> <td><math xmlns="http://www.w3.org/1998/Math/MathML"><mo>∠</mo></math>r</td> <td><math xmlns="http://www.w3.org/1998/Math/MathML"><mo>∠</mo></math>e</td> </tr> <tr> <td>I</td> <td>30°</td> <td>20°</td> <td>31°</td> </tr> <tr> <td>II</td> <td>40°</td> <td>25°</td> <td>40°</td> </tr> <tr> <td>III</td> <td>50°</td> <td>31°</td> <td>49°</td> </tr> </tbody> </table> <p> </p>', NULL, 1, 1, 27078, 1 FROM tq_chapters ch JOIN tq_offerings o ON o.id=ch.offeringId JOIN tq_boards b ON b.id=o.boardId JOIN tq_classes c ON c.id=o.classId JOIN tq_subjects sj ON sj.id=o.subjectId WHERE b.code='CBSE' AND c.name='Class 10' AND sj.name='Physics' AND ch.name='Light Reflection & Refraction';
